const english = Object.fromEntries(Object.entries(dictionary).map(([en, vi]) => [vi, en]))

function translateText(text: string, language: Language): string {
    const table = language === "vi" ? dictionary : english
    const word = (value: string) => {
        const core = value.trim()
        const translated = table[core]
        return translated === undefined ? value : value.slice(0, value.length - value.trimStart().length) + translated + value.slice(value.trimEnd().length)
    }
    const direct = word(text)
    if (direct !== text || !text.includes("<")) return direct
    return text.replace(/(^|>)([^<>]+)(?=<|$)/g, (_, prefix, value) => prefix + word(value))
}

function translateValue(value: any, language: Language, depth = 0): any {
    if (depth > 24) return value
    if (typeof value === "string") return translateText(value, language)
    if (!value || typeof value !== "object") return value
    if (React.isValidElement(value)) {
        const props = translateValue(value.props, language, depth + 1)
        return props === value.props ? value : React.cloneElement(value, props)
    }
    if (Array.isArray(value)) {
        const changed = value.map(item => translateValue(item, language, depth + 1))
        return changed.some((item, index) => item !== value[index]) ? changed : value
    }
    if (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) return value
    let changed = false
    const output: Record<string, any> = {}
    for (const [key, item] of Object.entries(value)) {
        const skip = /^(style|variants|variant|id|key|ref|href|src|srcSet|url|className|on[A-Z]|data-|aria-controls|aria-labelledby)/.test(key)
        output[key] = skip ? item : translateValue(item, language, depth + 1)
        if (output[key] !== item) changed = true
    }
    return changed ? output : value
}

export function withBotanikaLanguage(Component: ComponentType<any>): ComponentType<any> {
    const Translated = React.forwardRef<any, any>((props, ref) => {
        const initial: Language = "en"
        const [language, setLanguage] = React.useState<Language>(initial)
        React.useEffect(() => {
            const host = window as LanguageWindow
            if (!host.__botanikaInlineLanguage) host.__botanikaInlineLanguage = readInlineLanguage()
            const sync = () => setLanguage(readInlineLanguage())
            sync()
            window.addEventListener(languageEvent, sync)
            return () => window.removeEventListener(languageEvent, sync)
        }, [])
        // Translate the whole page too (the language picker that used to start this
        // lives in the mobile menu and is not mounted until the menu opens).
        React.useEffect(() => mountPageTranslation(), [])
        const translated = React.useMemo(() => translateValue(props, language), [props, language])
        const rotatingText = Object.values(props).some(value => Array.isArray(value) && value.some(item => item && typeof item === "object" && typeof item.text === "string" && /^(Secure Storage|Private AI|Infinite Scale|Lưu trữ an toàn|AI riêng tư|Mở rộng không giới hạn)$/.test(item.text)))
        return <Component key={rotatingText ? language : undefined} {...translated} ref={ref} lang={language} />
    })
    Translated.displayName = "BotanikaInlineLanguage"
    return Translated
}

/** Switches the Research card using editable bilingual CMS fields */
export function withResearchLanguage(Component: ComponentType<any>): ComponentType<any> {
    const ResearchCard = React.forwardRef<any, any>((props, ref) => {
        const [language, setLanguage] = React.useState<Language>("en")
        React.useEffect(() => {
            const host = window as LanguageWindow
            const sync = () => setLanguage(readInlineLanguage())
            sync()
            window.addEventListener(languageEvent, sync)
            return () => window.removeEventListener(languageEvent, sync)
        }, [])
        const output = { ...props }
        if (language === "vi") {
            const fields = [
                ["zb7ih2K4q", "zds1tt_KS", "title", "titleVI"],
                ["qQuB27Oyk", "rFKEy7Ho0", "sub", "subVI"],
            ]
            for (const [targetId, sourceId, targetName, sourceName] of fields) {
                const translated = props[sourceId] ?? props[sourceName]
                if (typeof translated !== "string" || !translated.trim()) continue
                output[targetId] = translated
                if (targetName in props) output[targetName] = translated
            }
        }
        const gradient = {
            start: typeof props.M2liLH37i === "string" ? props.M2liLH37i : "#181818",
            end: typeof props.jezsa3KIu === "string" ? props.jezsa3KIu : "#747474",
            angle: Number.isFinite(Number(props.RLEB7xa4j)) ? Number(props.RLEB7xa4j) : 135,
        }
        return <ResearchIconGradientContext.Provider value={gradient}><Component {...output} ref={ref} lang={language} /></ResearchIconGradientContext.Provider>
    })
    ResearchCard.displayName = "BotanikaResearchLanguage"
    return ResearchCard
}

