type ResearchIconGradient = { start: string; end: string; angle: number }
const ResearchIconGradientContext = React.createContext<ResearchIconGradient>({
    start: "#181818", end: "#747474", angle: 135,
})

/** Applies a linear gradient to the CMS-selected icon's own SVG shapes */
export function withResearchGradientIcon(Component: ComponentType<any>): ComponentType<any> {
    const GradientIcon = React.forwardRef<any, any>((props, ref) => {
        const gradient = React.useContext(ResearchIconGradientContext)
        const paintId = "botanika-icon-" + React.useId().replace(/[^a-zA-Z0-9_-]/g, "")
        const radians = gradient.angle * Math.PI / 180
        const dx = 50 * Math.sin(radians)
        const dy = -50 * Math.cos(radians)
        const scope = `[data-botanika-gradient="${paintId}"]`
        const shapes = "path,rect,circle,ellipse,polygon,polyline,line,use"
        const fill = `${scope} svg:not([data-gradient-paint]) :is(${shapes}):not([fill="none"])`
        const stroke = `${scope} svg:not([data-gradient-paint]) :is(${shapes})[stroke]:not([stroke="none"])`
        return (
            <div data-botanika-gradient={paintId} style={{ width: 30, height: 30, ...props.style, position: props.style?.position ?? "relative" }}>
                <svg data-gradient-paint aria-hidden="true" width="0" height="0" style={{ position: "absolute", pointerEvents: "none" }}>
                    <defs>
                        <linearGradient id={paintId} x1={`${50-dx}%`} y1={`${50-dy}%`} x2={`${50+dx}%`} y2={`${50+dy}%`}>
                            <stop offset="0%" stopColor={gradient.start}/>
                            <stop offset="100%" stopColor={gradient.end}/>
                        </linearGradient>
                    </defs>
                </svg>
                <style>{`${fill}{fill:url(#${paintId}) !important}${stroke}{stroke:url(#${paintId}) !important}`}</style>
                <Component {...props} ref={ref} style={{ ...props.style, position: "relative", left: 0, top: 0, width: "100%", height: "100%" }}/>
            </div>
        )
    })
    GradientIcon.displayName = "BotanikaResearchGradientIcon"
    return GradientIcon
}

const languageStorageKey = "botanika-language"
export function readInlineLanguage(): Language {
    if (typeof window === "undefined") return "en"
    const host = window as LanguageWindow
    if (host.__botanikaInlineLanguage) return host.__botanikaInlineLanguage
    let stored: string | null = null
    try { stored = localStorage.getItem(languageStorageKey) } catch {}
    return stored === "vi" || (!stored && /^\/vi(?:\/|$)/.test(location.pathname)) ? "vi" : "en"
}
export function setInlineLanguage(language: Language) {
    ;(window as LanguageWindow).__botanikaInlineLanguage = language
    try { localStorage.setItem(languageStorageKey, language) } catch {}
    document.documentElement.lang = language
    window.dispatchEvent(new Event(languageEvent))
}
let translationUsers = 0
let stopPageTranslation: (() => void) | undefined
export function mountPageTranslation() {
    translationUsers++
    if (!stopPageTranslation) {
        const originals = new WeakMap<Text, { source: string; rendered: string }>()
        let frame = 0
        const update = () => {
            frame = 0
            const language = readInlineLanguage()
            document.documentElement.lang = language
            const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
            let node: Text | null
            while ((node = walker.nextNode() as Text | null)) {
                const parent = node.parentElement
                if (!parent || parent.closest("script,style,textarea,[contenteditable=true],[data-botanika-no-translate]")) continue
                const current = node.data
                const previous = originals.get(node)
                const source = previous && previous.rendered === current ? previous.source : current
                const rendered = translateText(source, language)
                originals.set(node, { source, rendered })
                if (current !== rendered) node.data = rendered
            }
        }
        const schedule = () => { if (!frame) frame = requestAnimationFrame(update) }
        const observer = new MutationObserver(schedule)
        observer.observe(document.body, { subtree: true, childList: true, characterData: true })
        window.addEventListener(languageEvent, schedule)
        schedule()
        stopPageTranslation = () => {
            observer.disconnect()
            window.removeEventListener(languageEvent, schedule)
            if (frame) cancelAnimationFrame(frame)
        }
    }
    return () => { if (--translationUsers === 0) { stopPageTranslation?.(); stopPageTranslation = undefined } }
}
